SELECT

FROM report r
LEFT JOIN `user` u ON r.report_user_id = u.id


        AND r.status = #{status}


        AND r.target_type = #{targetType}


ORDER BY r.create_time DESC

SELECT

FROM report r

    r.report_user_id = #{reportUserId}

        AND r.status = #{dto.status}


        AND r.target_type = #{dto.targetType}


ORDER BY r.create_time DESC

SELECT


WHERE r.id = #{id}
  AND r.report_user_id = #{reportUserId}
LIMIT 1
